  "landing.faq.title": "अक्सर पूछे जाने वाले प्रश्न",
  "landing.faq.q1": "क्या Second Brain सिर्फ एक चैटबॉट है?",
  "landing.faq.a1": "नहीं। यह एक व्यक्तिगत शिक्षण वातावरण है: यह आपकी सामग्री को समझता है, इसे सिखाता है, और समय के साथ आपकी प्रगति को याद रखता है।",
  "landing.faq.q2": "क्या मैं कई PDF और दस्तावेजों के साथ काम कर सकता हूँ?",
  "landing.faq.a2": "हाँ। आप PDF, फ़ोटो, स्कैन और नोट्स को एक पूरे विषय में समूहीकृत कर सकते हैं और किसी एक फ़ाइल से नहीं, बल्कि पूरे सेट से सीख सकते हैं।",
  "landing.faq.q3": "मैं AI प्रोफेसर के साथ क्या कर सकता हूँ?",
  "landing.faq.a3": "पढ़ाई करें, स्पष्टीकरण मांगें, चर्चा करें, निर्देशित सत्र चलाएं और अभ्यासों के साथ अभ्यास करें — आपके स्तर के अनुकूल।",
  "landing.faq.q4": "क्या मैं AI प्रोफेसर से ज़ोर से बात कर सकता हूँ?",
  "landing.faq.a4": "हाँ। बोलकर बातचीत, मौखिक अभ्यास और मौखिक परीक्षाएं आपको ज़ोर से अभ्यास करने देती हैं।",
  "landing.faq.q5": "डिजिटल ट्विन क्या है?",
  "landing.faq.a5": "आपकी सीखने की प्रक्रिया की एक व्यक्तिगत स्मृति — जिसे आप समझते हैं, जिस पर महारत हासिल है, जिसे भूल जाते हैं और जिसका लक्ष्य रखते हैं।",
  "landing.faq.q6": "स्मृति और समीक्षा कैसे काम करती है?",
  "landing.faq.a6": "एक स्पेस्ड-रिपीटेशन इंजन (FSRS) सही समय पर समीक्षाओं का समय निर्धारित करता है ताकि आप कम प्रयास में अधिक याद रख सकें।",
  "landing.faq.q7": "क्या मैं अपने शैक्षणिक कार्य के लिए Second Brain का उपयोग कर सकता हूँ?",
  "landing.faq.a7": "हाँ। एकेडमिक वर्कस्पेस लैब, होमवर्क, रिपोर्ट और बहुत कुछ में मार्गदर्शन करता है — केवल उत्तर ही नहीं, बल्कि तरीका सिखाता है।",
  "landing.faq.q8": "भाषा सीखना कैसे काम करता है?",
  "landing.faq.a8": "इमर्शन, बातचीत, मौखिक अभ्यास और शैडोइंग — और आपके अपने पाठ्यक्रम की भाषा को समझने में मदद।",
  "landing.faq.q9": "मेरे डेटा की सुरक्षा कैसे की जाती है?",
  "landing.faq.a9": "आपका सीखने का डेटा आपके अनुभव को बेहतर बनाता है। आप अपने खाते को नियंत्रित करते हैं और अपनी प्रोफ़ाइल से अपने डेटा का प्रबंधन कर सकते हैं।",
