  "landing12.how.consolidate.title": "मजबूत करें",
  "landing12.how.consolidate.desc": "समीक्षा करें कि साक्ष्य के अनुसार क्या कमज़ोर है।",
  "landing12.how.continue.title": "जारी रखें",
