  "landing12.nba.kicker": "अगली सर्वश्रेष्ठ कार्रवाई",
  "landing12.nba.title": "जानें कि अभी किस पर ध्यान देने की आवश्यकता है",
  "landing12.nba.lead": "सिफ़ारिशें वास्तविक संदर्भ को मिलाती हैं और बताती हैं कि वे क्यों उपयोगी हैं। ये सुझाव हैं, कभी भी अदृश्य कमांड नहीं।",
  "landing12.nba.english": "अपना अंग्रेज़ी पाठ्यक्रम फिर से शुरू करें",
