  "landing12.platform.status.coming-soon": "जल्द आ रहा है; अभी कोई सार्वजनिक डाउनलोड लिंक नहीं है",
  "landing12.download.kicker": "मल्टी-प्लेटफ़ॉर्म निरंतरता",
  "landing12.download.title": "Second Brain, आप जहाँ भी सीखें",
  "landing12.download.lead": "आज ही वेब अनुभव से शुरुआत करें। मोबाइल और डेस्कटॉप वितरण को ईमानदारी से दिखाया जाता है जैसे-जैसे यह उपलब्ध होता है।",
  "landing12.download.continuity": "सत्र मॉडल इस तरह से डिज़ाइन किया गया है कि आप एक डिवाइस पर शुरू कर सकते हैं और दूसरे पर फिर से शुरू कर सकते हैं।",
