  "landing12.features.group.practice": "अभ्यास करें और याद रखें",
  "landing12.features.group.practice.desc": "सक्रिय शिक्षण",
  "landing12.features.group.produce": "उपयोग करें और जारी रखें",
  "landing12.features.group.produce.desc": "कार्य और अगली कार्रवाई",
  "landing12.feature.brain.title": "मेरा मस्तिष्क",
  "landing12.feature.brain.desc": "अवधारणाओं, संबंधों, महारत, स्मृति और सीखने के इतिहास के लिए एक दृश्यमान संज्ञानात्मक ट्विन।",
  "landing12.feature.professor.title": "एआई प्रोफेसर",
  "landing12.feature.professor.desc": "एक शैक्षणिक पहचान जो पढ़ाती है, समझाती है, प्रश्न पूछती है, आकलन करती है और सक्रिय संदर्भ के अनुसार खुद को ढालती है।",
  "landing12.feature.learn.title": "सीखें",
  "landing12.feature.learn.desc": "पाठ, आवाज़ और स्रोतों के साथ समझने, सीखने, अभ्यास करने, शोध करने या निर्माण करने के लिए एक कंपोज़र।",
  "landing12.feature.documents.title": "दस्तावेज़ इंटेलिजेंस",
  "landing12.feature.documents.desc": "स्रोत ट्रेसबिलिटी के साथ एक दस्तावेज़ या सीमित बैच को आयात करें, समझें, प्रश्न पूछें और रूपांतरित करें।",
  "landing12.feature.review.title": "समीक्षा",
  "landing12.feature.review.desc": "वास्तविक समीक्षा इतिहास और अंतराल पर पुनरावृत्ति के माध्यम से उन चीज़ों को मजबूत करता है जिनके भुलाए जाने का जोखिम है।",
  "landing12.feature.research.title": "शोध",
  "landing12.feature.research.desc": "My Brain और लाइब्रेरी में त्वरित, स्रोत-आधारित या गहन जाँच; उद्धरण निरीक्षण योग्य बने रहते हैं।",
